'use strict';
// Lossless GitHub Issue #1 comment snapshot, LZW16 little-endian + Base64.
// Usage: node issue-1-comments-2026-10-24-export.cjs [output.json]
const fs=require('node:fs');
const input='';
const b=Buffer.from(input,'base64');
if(b.length%2)throw Error('Invalid LZW payload length');
const d=Array.from({length:256},(_,i)=>String.fromCharCode(i));
let next=256;const first=b.readUInt16LE(0);let prev=d[first];
if(prev===undefined)throw Error('Invalid first LZW code');
const out=[prev];
for(let i=2;i<b.length;i+=2){const code=b.readUInt16LE(i);let entry=d[code];if(entry===undefined){if(code!==next)throw Error('Invalid LZW code '+code);entry=prev+prev[0];}out.push(entry);if(next<65536)d[next++]=prev+entry[0];prev=entry;}
const json=Buffer.from(out.join(''),'latin1').toString('utf8');
const obj=JSON.parse(json);
if(obj.issue_number!==1||obj.comment_count!==obj.comments.length)throw Error('Comment validation failed');
const destination=process.argv[2]||'issue-1-comments-2026-10-24.json';
fs.writeFileSync(destination,json);
console.log(JSON.stringify({destination,comments:obj.comment_count,bytes:Buffer.byteLength(json)}));
